use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs::{self,File},io::{Read,Seek,SeekFrom},path::{Path,PathBuf}};
type Result<T>=std::result::Result<T,String>;
#[derive(Default)]pub struct Prefixes{pub declarations:BTreeMap<PathBuf,BTreeMap<u64,String>>,cached:BTreeMap<(PathBuf,u64),String>,pub bytes_read:u64,pub calls:u64,pub forward:bool}
impl Prefixes{
 pub fn declare(&mut self,path:&Path,end:u64,expected:&str)->Result<()>{if expected.len()!=64{return Err("PREFIX_HASH_SHAPE".into())}let list=self.declarations.entry(path.into()).or_default();if let Some(old)=list.get(&end){if old!=expected{return Err("CONFLICTING_PREFIX_FRONTIER".into())}}list.insert(end,expected.into());Ok(())}
 pub fn seal_forward(&mut self)->Result<()>{if !self.forward{return Ok(())}for(path,frontiers)in &self.declarations{let before=crate::frozen_observe::source_identity(path)?;let mut options=fs::OpenOptions::new();options.read(true);#[cfg(windows)]{use std::os::windows::fs::OpenOptionsExt;options.share_mode(3);}let mut file=options.open(path).map_err(|_|"PREFIX_INPUT_UNAVAILABLE")?;let end=*frontiers.keys().next_back().unwrap();if file.metadata().map_err(|_|"PREFIX_INPUT_METADATA")?.len()<end{return Err("PREFIX_TRUNCATED".into())}let mut hash=Sha256::new();let mut cursor=0u64;let mut buffer=[0u8;65536];for(&at,expected)in frontiers{while cursor<at{let n=file.read(&mut buffer[..(at-cursor).min(65536)as usize]).map_err(|_|"PREFIX_READ")?;if n==0{return Err("PREFIX_TRUNCATED".into())}hash.update(&buffer[..n]);cursor+=n as u64;self.bytes_read+=n as u64;}let observed=format!("{:x}",hash.clone().finalize());if &observed!=expected{return Err("PREFIX_HASH_MISMATCH".into())}if at>0{file.seek(SeekFrom::Start(at-1)).map_err(|_|"PREFIX_READ")?;let mut byte=[0u8;1];file.read_exact(&mut byte).map_err(|_|"PREFIX_READ")?;if byte[0]!=b'\n'{return Err("PREFIX_NONRECORD_FRONTIER".into())}file.seek(SeekFrom::Start(at)).map_err(|_|"PREFIX_READ")?;}self.cached.insert((path.clone(),at),observed);}if crate::frozen_observe::source_identity(path)?!=before{return Err("PREFIX_REPLACED".into())}}
 Ok(())}
 pub fn hash(&mut self,path:&Path,end:u64)->Result<String>{self.calls+=1;if self.forward{return self.cached.get(&(path.into(),end)).cloned().ok_or("UNDECLARED_PREFIX_FRONTIER".into())}let mut file=File::open(path).map_err(|_|"PREFIX_INPUT_UNAVAILABLE")?;if file.metadata().map_err(|_|"PREFIX_INPUT_METADATA")?.len()<end{return Err("PREFIX_TRUNCATED".into())}let mut hash=Sha256::new();let mut left=end;let mut buffer=[0u8;65536];while left>0{let n=file.read(&mut buffer[..left.min(65536)as usize]).map_err(|_|"PREFIX_READ")?;if n==0{return Err("PREFIX_TRUNCATED".into())}hash.update(&buffer[..n]);left-=n as u64;self.bytes_read+=n as u64;}Ok(format!("{:x}",hash.finalize()))}
}
